def reconnect(timeout: float = CALL_GATE_SECONDS) -> dict:
    """Rebuild the provider from the current configuration without dropping
    in-flight calls.

    A fresh instance is built from the factory named by ``KEYMGR_PROVIDER``,
    contract-validated, configured against the bound data directory and health
    checked; only a healthy instance is swapped in. In-flight calls finish on
    the OLD instance while new calls wait behind the shared five-second gate.
    On any failure (drain/build/configure/health timeout) the previously active
    instance is retained untouched and :class:`ProviderUnavailable` is raised.
    Returns the new status body on success.
    """
    candidate_holder: dict = {}

    def builder(deadline: float) -> None:
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            raise ProviderReconnectPending(
                "reconnect exceeded the shared five-second budget"
            )
        # Build + contract validation + configure (factory work happens while
        # new calls are held at the gate but no condition lock is held).
        candidate = _build_current_provider()
        # The health check shares the same five-second budget: give it whatever
        # of the budget remains. A slow/blocked probe is a failed reconnect.
        try:
            ready = _health_with_deadline(candidate, deadline)
        except Exception:
            raise ProviderUnavailable("provider health check failed")
        if not ready:
            raise ProviderUnavailable("provider reported unhealthy")
        candidate_holder["provider"] = candidate

    _gate.swapping(builder, timeout=timeout)

    candidate = candidate_holder.get("provider")
    if candidate is None:  # defensive; builder raises on failure
        raise ProviderUnavailable("provider reconnect did not produce an instance")

    global _provider
    with _provider_lock:
        _provider = candidate
    return _status_for(candidate)


def _health_with_deadline(provider, deadline: float) -> bool:
    """Run health() bounded by the reconnect deadline.

    health() implementations are normally immediate; a probe that blocks past
    the shared budget is treated as unavailable without waiting longer.
    """
    result: dict = {}

    def probe() -> None:
        try:
            result["ready"] = provider.health() is True
        except Exception:
            result["ready"] = False

    thread = threading.Thread(target=probe, daemon=True)
    thread.start()
    thread.join(timeout=max(0.0, deadline - time.monotonic()))
    if thread.is_alive():
        return False
    return bool(result.get("ready"))

